function solve(args) {
  const grid = args[0];
  const k = args[1];
  const n = grid.length;
  const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
  const best = new Array(k);
  const visited = new Array(k);
  let found = false;

  function dfs(r, c, depth) {
    if (found) return;
    best[depth] = grid[r][c];
    if (depth === k - 1) {
      found = true;
      return;
    }
    const nextDepth = depth + 1;
    const candidates = [];
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
        candidates.push([grid[nr][nc], nr, nc]);
      }
    }
    candidates.sort((a, b) => a[0] - b[0]);
    for (const [, nr, nc] of candidates) {
      if (found) return;
      if (best[nextDepth] !== undefined && grid[nr][nc] > best[nextDepth]) continue;
      dfs(nr, nc, nextDepth);
    }
  }

  const starts = [];
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      starts.push([grid[r][c], r, c]);
    }
  }
  starts.sort((a, b) => a[0] - b[0]);

  for (const [, r, c] of starts) {
    if (found) break;
    if (best[0] !== undefined && grid[r][c] > best[0]) continue;
    dfs(r, c, 0);
  }

  return best.slice();
}

