function solve(args) {
  const grid = args[0];
  const k = args[1];
  const n = grid.length;
  const total = n * n;

  const values = [];
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      values.push(grid[r][c]);
    }
  }
  values.sort((a, b) => a - b);

  const minVal = values[0];

  const positions = new Map();
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      const v = grid[r][c];
      if (!positions.has(v)) positions.set(v, []);
      positions.get(v).push([r, c]);
    }
  }

  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];

  function canReach(startCells, steps) {
    if (steps === 0) return true;
    let frontier = startCells;
    const seen = new Set();
    for (const [r, c] of frontier) seen.add(r * n + c);
    for (let s = 0; s < steps; s++) {
      const next = [];
      const nextSeen = new Set();
      for (const [r, c] of frontier) {
        for (const [dr, dc] of dirs) {
          const nr = r + dr;
          const nc = c + dc;
          if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
            const key = nr * n + nc;
            if (!nextSeen.has(key)) {
              nextSeen.add(key);
              next.push([nr, nc]);
            }
          }
        }
      }
      frontier = next;
      if (frontier.length === 0) return false;
    }
    return true;
  }

  const result = [];
  let currentCells = null;

  for (let pos = 0; pos < k; pos++) {
    const remaining = k - pos - 1;
    let chosen = null;
    let chosenCells = null;

    for (const v of values) {
      const cells = positions.get(v);
      let validCells = null;

      if (currentCells === null) {
        validCells = cells;
      } else {
        validCells = [];
        for (const [r, c] of cells) {
          for (const [pr, pc] of currentCells) {
            if (Math.abs(r - pr) + Math.abs(c - pc) === 1) {
              validCells.push([r, c]);
              break;
            }
          }
        }
      }

      if (validCells.length === 0) continue;

      if (canReach(validCells, remaining)) {
        chosen = v;
        chosenCells = validCells;
        break;
      }
    }

    result.push(chosen);
    currentCells = chosenCells;
  }

  return result;
}

