  const minVal = 1;

  const startCells = [];
  for (let r=0;r<n;r++) for (let c=0;c<n;c++) if (grid[r][c] === minVal) startCells.push([r,c]);

  const memo = new Map();

  function feasible(r, c, steps) {
    if (steps === 0) return true;
    const key = r*total*1000 + c*1000 + steps;
    if (memo.has(key)) return memo.get(key);
