    for (const [dr,dc] of dirs) {
      const nr=r+dr, nc=c+dc;
      if (inb(nr,nc) && feasible(nr,nc,steps-1)) { res = true; break; }
    }
    memo.set(key, res);
    return res;
  }

  const result = [];
  let curR = -1, curC = -1;
  let first = true;

  for (let pos = 0; pos < k; pos++) {
    const remaining = k - pos - 1;
    let bestVal = Infinity;
    let bestR = -1, bestC = -1;

    if (first) {
      for (const [r,c] of startCells) {
        if (feasible(r,c,remaining)) {
          if (grid[r][c] < bestVal) { bestVal = grid[r][c]; bestR=r; bestC=c; }
        }
      }
    } else {
      for (const [dr,dc] of dirs) {
        const nr=curR+dr, nc=curC+dc;
        if (inb(nr,nc) && feasible(nr,nc,remaining)) {
          if (grid[nr][nc] < bestVal) { bestVal = grid[nr][nc]; bestR=nr; bestC=nc; }
        }
      }
    }

    result.push(bestVal);
    curR = bestR; curC = bestC;
    first = false;
  }

  return result;
}

