    const res = [];
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < n && nc >= 0 && nc < n) res.push([nr, nc]);
    }
    return res;
  }

  function bestFrom(r, c, steps) {
    if (steps === 1) return [grid[r][c]];
    let best = null;
    for (const [nr, nc] of neighbors(r, c)) {
      const sub = bestFrom(nr, nc, steps - 1);
      const cand = [grid[r][c]].concat(sub);
      if (best === null || compare(cand, best) < 0) best = cand;
    }
